  let moonAmb = vec3f(0.055, 0.070, 0.115) * moonUp * u.night
              * (0.55 + 2.6 * hg(clamp(moonDot, -1.0, 1.0), 0.52));
  // ── 贴图云。摆位就是构图：主角云在右、中云在左低处、小朵在高处，
  // 标题附近天生留空——负空间靠构图给，不靠遮罩挖
  let dayA2 = smoothstep(-0.10, 0.22, sunDir.y);
  let sunPk = max(sunCol.r, max(sunCol.g, sunCol.b));
